import sys, json, random, time
sys.path.insert(0,'/workspace/submission')
import main as impl

def timeit(nserv, L, k, rng):
    svc = ['t%d'%i for i in range(nserv)]
    specs = [tuple(rng.choice(svc) for _ in range(L)) for _ in range(k)]
    req = {'services':svc,'rules':[{'action':'allow','when':{'op':'and','args':[{'op':'contains','path':list(p)} for p in specs]}}],
           'queries':[[svc[0],svc[1]]]}
    t0=time.time()
    got = impl.process(json.dumps(req).encode())
    t1=time.time()
    parsed = impl.parse_request(json.loads(json.dumps(req)))
    try:
        order = impl.build_product(parsed['atoms'], nserv)[0]
        prod = len(order)
    except impl.ComplexityError:
        return ('>cap', t1-t0, None)
    if got.startswith('{"ok":false'):
        return ('ERR', t1-t0, prod)
    m = len(json.loads(got)['dfa']['next'])
    return ('ok', t1-t0, (prod, m, len(got)))

rng = random.Random(17)
best = None
for nserv in (8, 10, 12, 14, 16, 18, 20, 24):
    for L in (3, 4, 5):
        for k in (10, 8):
            res = timeit(nserv, L, k, rng)
            if res[0] == 'ok':
                prod, m, nbytes = res[2]
                print('nserv=%2d L=%d k=%2d product=%-6d min=%-6d bytes=%-8d time=%.2fs' % (nserv,L,k,prod,m,nbytes,res[1]))
                if best is None or res[1] > best[1]:
                    best = (nserv,L,k,res)
            else:
                print('nserv=%2d L=%d k=%2d %s time=%.2fs' % (nserv,L,k,res[0],res[1]))
print('best', best[:3] if best else None, best[1] if best else None)
EOF
